root=Path(__file__).resolve().parents[1]
def data_image(p):return 'data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode('ascii')
rows=[
 ('帽子与整体轮廓','宽帽檐与头部连成一个较饱满的轮廓，后侧下压。','帽檐收窄、抬高，帽冠更竖，头和帽像两个独立零件。','拆件重绘 + 帽子单独缩放/定位。先恢复原图轮廓，再定帽骨。'),
 ('脸、刘海与侧发','头发轮廓更收，脸部位置较高，朝右的感觉更清楚。','头发和头部整体偏大，脸的位置偏低；发束、脸形和眼睛也已改变。','头部是另一张重绘图，之后又被整体放大。需要按母版恢复局部比例与位置。'),
 ('领口与肩颈','颈圈、领口、两侧披风翻领相互分开，层次能读清。','颈圈和领口挤在一起，翻领遮挡混乱，肩颈空间变窄。','头、衣服和披风重复携带领口内容，又没有按原图配准。'),
 ('躯干、腰带、下摆','腰带斜向、身体略转，服装有自然的不对称。','身体更接近正面，腰带趋平；下摆偏宽、偏低，露出的腿段被压短。','衣服被单独重画成正面件，躯干摆位也没有对齐母版。'),
 ('右臂与主握手','袖子轮廓连续，手掌和袖口体积明确，肘部轻弯。','手臂变细，肘部像插接的小段；手掌太小，握杖关系缺少体积。','按预设骨长缩放拆件；IK 只保证端点相接，不保证美术正确。'),
 ('自然下垂的左手','指尖位于衣服下摆以下，接近大腿上段。','手停在下摆上方，显得缩起、偏短，肩臂也偏紧。','左手目标点与臂长没有按母版校准。这是明确的摆位错误。'),
 ('腿、脚和重心','缠绷带的右腿有斜向，双脚与身体形成轻微重心差。','两腿更直、更接近平行；足部形状也被简化成另一套画法。','整条腿重绘 + 脚踝独立定位，原来的站姿线条丢失。'),
 ('法杖','杖身向左上倾；木叉、红珠、握带、杖底的比例彼此固定。','法杖整体偏短、更直，杖头相对偏低；木叉与杖底造型变化明显。','道具被重画后，又单独缩放和旋转。形状、长度和倾角均要回到母版。'),
 ('披风','跟随转身形成不对称边缘，领部与肩部关系明确。','更像一片对称的三角披布，下端和开口位置都偏离母版。','正面披风件无法直接复原略转身的原图；还叠加了遮挡误差。'),
]
packed={
 'skeleton':json.loads((root/'export/megumin.json').read_text(encoding='utf-8')),
 'atlas':(root/'export/megumin.atlas').read_text(encoding='utf-8'),
 'pages':{p.name:data_image(p) for p in (root/'export').glob('*.png')},
 'reference':data_image(root.parent/'megumin-concepts-20261009/quartet/idle-02-right-hand.png'),
 'official':data_image(root.parent/'isekai-quartet-references-20261009/originals/L01-official-standing.png'),
}
table=''.join('<tr>'+''.join(f'<{tag}>{html.escape(text)}</{tag}>' for tag,text in [('th',r[0]),('td',r[1]),('td',r[2]),('td',r[3])])+'</tr>' for r in rows)
document='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>惠惠 Idle · 母版还原对照</title><style>
:root{--bg:#f5f0e7;--surface:#fffcf6;--border:#d8cbbf;--text:#322b28;--text-dim:#7b7067;--red:#a53d32;--sage:#537866;--gold:#bd8c35}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:15px/1.75 'Microsoft YaHei','PingFang SC',sans-serif}main{max-width:1180px;margin:auto;padding:30px 28px 55px}.kicker{font:11px Consolas,monospace;letter-spacing:.17em;color:var(--red)}h1{font-size:30px;line-height:1.35;margin:7px 0 12px}h2{font-size:20px;margin:0 0 13px}.intro{max-width:950px;font-size:15px;margin:0 0 19px}.intro strong{color:var(--red)}.controls{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;border-top:1px solid var(--border);padding:16px 0}.buttons{display:flex;gap:8px}button{font:inherit;padding:6px 14px;border:1px solid var(--border);border-radius:4px;color:var(--text);background:var(--surface);cursor:pointer}button[aria-pressed=true]{background:var(--red);border-color:var(--red);color:#fff}button:focus-visible{outline:3px solid var(--gold);outline-offset:3px}label{font-size:13px;color:var(--text-dim);display:flex;align-items:center;gap:8px}input{accent-color:var(--red)}.views{display:grid;grid-template-columns:1fr 1fr;background:var(--surface);border:1px solid var(--border);border-radius:6px;position:relative;overflow:hidden}.view{min-width:0;position:relative;height:450px}.view+.view{border-left:1px solid var(--border)}canvas{width:100%;height:100%;display:block}.label{position:absolute;top:12px;left:17px;font-size:12px;color:var(--text-dim);z-index:2;pointer-events:none;background:var(--surface);padding:0 4px}.views.overlay{display:block}.views.overlay .current{position:absolute;inset:0;z-index:1;pointer-events:none}.views.overlay .reference{border:0}.views.overlay .reference .label{left:auto;right:17px}.caption{font-size:12px;color:var(--text-dim);margin:9px 0 27px}.summary{display:grid;grid-template-columns:1.2fr 1fr;gap:28px;border-top:1px solid var(--border);padding-top:23px;margin-bottom:30px}.summary p{margin:0 0 9px}.order{display:grid;gap:8px;margin:0;padding-left:23px}.table-wrap{overflow:auto;border:1px solid var(--border);border-radius:5px;background:var(--surface)}table{border-collapse:collapse;width:100%;font-size:13px;min-width:780px}th,td{text-align:left;vertical-align:top;padding:13px 15px;border-bottom:1px solid var(--border)}thead th{background:#eadfd2;color:var(--text);font-weight:600}tbody th{width:135px;white-space:nowrap;color:var(--red)}td{width:29%;overflow-wrap:break-word}tr:last-child>*{border:0}.official{display:grid;grid-template-columns:210px 1fr;gap:24px;align-items:center;margin-top:25px;border-top:1px solid var(--border);padding-top:20px}.official img{height:220px;max-width:100%;object-fit:contain}.official p{max-width:780px;margin:6px 0;font-size:13px;color:var(--text-dim)}a{color:var(--red);text-underline-offset:3px}footer{border-top:1px solid var(--border);margin-top:25px;padding-top:14px;font-size:12px;color:var(--text-dim)}#error{color:var(--red)}@media(max-width:760px){main{padding:22px 15px}.views:not(.overlay){grid-template-columns:1fr 1fr}.view{height:405px}h1{font-size:24px}.label{font-size:10px;left:6px}.summary{grid-template-columns:1fr;gap:15px}.official{grid-template-columns:125px 1fr;gap:12px}.official img{height:160px}}@media(prefers-color-scheme:dark){:root{--bg:#24211e;--surface:#312b27;--border:#584a40;--text:#ece4db;--text-dim:#b5a79b;--red:#e68d76;--sage:#8ba992;--gold:#d8b266}thead th{background:#45392f}}
</style></head><body><main><div class="kicker">MEGUMIN / IDLE RESTORATION AUDIT / 2026.10.09</div><h1>静止时，已经偏离了母版。</h1><p class="intro">当前问题主要出在<strong>拆件重绘和重新拼装</strong>。动画可播放、手能锁在杖上，并不代表角色已被忠实还原。这里固定当前 Spine 的 idle 首帧，与此前选用的右手持杖母版对照。</p><div class="controls"><div class="buttons"><button id="side" aria-pressed="true">等高并排</button><button id="overlay" aria-pressed="false">重叠看轮廓</button></div><label>当前 Spine 不透明度 <input id="opacity" type="range" min="0" max="100" value="50" aria-label="当前 Spine 不透明度"><output id="percent">50%</output></label></div><div class="views" id="views"><div class="view current"><div class="label">当前 Spine · idle t = 0</div><canvas id="current" aria-label="当前 Spine idle 首帧"></canvas></div><div class="view reference"><div class="label">此前选用母版 · 右手持杖</div><canvas id="reference" aria-label="此前选用的右手持杖母版"></canvas></div></div><p class="caption">按身高近似等高、脚底线对齐，横向按双脚中点近似对齐。叠图用于观察轮廓，不作为像素级误差测量。对照页保留本次检查时的数据快照。</p><div id="error" role="alert"></div><section class="summary"><div><h2>最需要先纠正的三件事</h2><p><strong>一，静态轮廓：</strong>帽子、头发、脸与躯干的比例关系。</p><p><strong>二，自然站姿：</strong>左手应垂到下摆以下，右臂和手掌应有母版中的体积，法杖与腿部应保留原来的斜向。</p><p><strong>三，服装层次：</strong>颈圈、领口、披风翻领不能重复叠在一起。</p></div><div><h2>制作顺序需要调整</h2><ol class="order"><li>锁定母版，先还原同一张静态立绘。</li><li>保留可见部位，只为被遮挡的部分补画。</li><li>通过静态对照后，按真实关节位置建立骨架。</li><li>最后制作呼吸、眨眼和其他动作；眨眼只改眼部。</li></ol></div></section><h2>逐项差异</h2><div class="table-wrap"><table><thead><tr><th>部位</th><th>母版</th><th>当前 idle</th><th>原因与修正方向</th></tr></thead><tbody>__TABLE__</tbody></table></div><section class="official"><img id="official" alt="异世界四重奏官网惠惠站立图"><div><h2>官方站立图是另一个层级的参考</h2><p>左侧是《异世界四重奏》官网 L01。它用于判断角色、服装和 Q 版风格；本次动画直接使用的目标，则应是上方已经确认的右手持杖母版。两者不能混着量尺寸。</p><p>当前生成母版本身也不是官方图的逐像素复刻；本次主要指出的是：从此前选用母版到 Spine 又发生了一轮额外偏移。</p><a href="https://isekai-quartet.com/character.html#Cat2">官方角色来源</a></div></section><footer>原始参考、拆件图和动画数据均未修改。本页用于确认问题，不代表已经修复。对照方法：官方 Spine WebGL 4.2 解析当前导出数据，固定 idle 首帧；母版保留原始 PNG。<br>相关文件：<a href="preview.html">动画样机</a> · <a href="README.md">制作说明</a></footer></main><script id="data" type="application/json">__DATA__</script><script>__RUNTIME__</script><script>
const p=JSON.parse(document.getElementById('data').textContent),q=id=>document.getElementById(id);let scene,sk,mode='side',bound;
const cv=q('current'),gl=cv.getContext('webgl',{alpha:true,premultipliedAlpha:true,antialias:true,preserveDrawingBuffer:true});
const ref=new Image();ref.src=p.reference;q('official').src=p.official;
function redraw(){if(!scene||!ref.complete)return;const w=cv.clientWidth,h=cv.clientHeight,dpr=Math.min(devicePixelRatio||1,2),base=h-26,paint=h-65,cx=w*.57,s=paint/bound.height;cv.width=Math.round(w*dpr);cv.height=Math.round(h*dpr);gl.viewport(0,0,cv.width,cv.height);gl.clearColor(0,0,0,0);gl.clear(gl.COLOR_BUFFER_BIT);scene.camera.position.set((w/2-cx)/s,(base-h/2)/s+bound.y,0);scene.camera.setViewport(w/s,h/s);scene.camera.update();scene.begin();scene.drawSkeleton(sk,false);scene.end();cv.style.opacity=mode==='overlay'?q('opacity').value/100:1;
const rc=q('reference'),rw=rc.clientWidth,rh=rc.clientHeight;rc.width=Math.round(rw*dpr);rc.height=Math.round(rh*dpr);const c=rc.getContext('2d');c.setTransform(dpr,0,0,dpr,0,0);c.clearRect(0,0,rw,rh);const rs=(rh-65)/1320;c.drawImage(ref,rw*.57-608*rs,rh-26-1348*rs,1147*rs,1371*rs);c.strokeStyle='#b8a89a';c.lineWidth=.6;c.beginPath();c.moveTo(10,rh-26);c.lineTo(rw-10,rh-26);c.stroke();}
function setMode(m){mode=m;q('views').classList.toggle('overlay',m==='overlay');q('side').setAttribute('aria-pressed',m==='side');q('overlay').setAttribute('aria-pressed',m==='overlay');redraw();}
q('side').onclick=()=>setMode('side');q('overlay').onclick=()=>setMode('overlay');q('opacity').oninput=()=>{q('percent').textContent=q('opacity').value+'%';if(mode!=='overlay')setMode('overlay');else redraw();};window.addEventListener('resize',redraw);ref.onload=redraw;
(async()=>{try{if(!gl)throw Error('浏览器未提供 WebGL');const atlas=new spine.TextureAtlas(p.atlas);await Promise.all(atlas.pages.map(page=>new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>{page.setTexture(new spine.GLTexture(gl,im));resolve()};im.onerror=reject;im.src=p.pages[page.name];})));const d=new spine.SkeletonJson(new spine.AtlasAttachmentLoader(atlas)).readSkeletonData(p.skeleton);sk=new spine.Skeleton(d);d.findAnimation('idle_loop').apply(sk,0,0,false,[],1,spine.MixBlend.setup,spine.MixDirection.mixIn);sk.updateWorldTransform(spine.Physics.update);const offset=new spine.Vector2(),size=new spine.Vector2();sk.getBounds(offset,size);bound={y:offset.y,height:size.y};scene=new spine.SceneRenderer(cv,gl);redraw();}catch(e){q('error').textContent=e.stack;console.error(e)}})();
</script></body></html>'''
document=document.replace('__TABLE__',table).replace('__DATA__',json.dumps(packed,separators=(',',':')).replace('</','<\\/')).replace('__RUNTIME__',(root/'vendor/spine-webgl-4.2.95.min.js').read_text(encoding='utf-8'))
out=root/'idle-comparison.html';out.write_text(document,encoding='utf-8')
diagrams=Path.home()/'.agent/diagrams';diagrams.mkdir(parents=True,exist_ok=True)
(diagrams/'megumin-idle-comparison.html').write_text(document,encoding='utf-8')
print(out)
